import json,copy
from pathlib import Path
base=Path('content/isc2-cc-2026/learning/published');l=copy.deepcopy(json.loads((base/'lessons/lesson-d1-09-frameworks.json').read_text(encoding='utf-8')))
def pair(en,th):return {'en':en,'th':th}
def row(*a):return [pair(*x) for x in a]
slides=[]
def add(suffix,kind,title,lead,rows,detail,foot):
 s=copy.deepcopy(l['slides'][0]);s.update(id='slide-'+suffix,title=pair(*title),layoutId='control-categories-'+kind,rendererId='interactive' if kind=='classify' else 'comparison');s['blocks']=[{'kind':'text','text':pair(*lead)},{'kind':'table','caption':pair('Course concepts and original teaching examples','แนวคิดจากโน้ตและตัวอย่างแต่งขึ้นเพื่อเรียน'),'columns':[pair('Concept','แนวคิด'),pair('Meaning or action','ความหมายหรือการกระทำ'),pair('Context','บริบท')],'rows':rows},{'kind':'text','text':pair(*detail)},{'kind':'text','text':pair(*foot)}];s['referenceIds']=['ref-outline','ref-a','ref-b']+(['ref-nist'] if kind in ['together','decision'] else []);slides.append(s)
add('01-category-and-purpose','axes',('Category asks how a control is implemented.','Category ถามว่ามาตรการทำงานผ่านอะไร'),('Separate the mechanism from the security job it performs.','แยกกลไกที่ใช้ ออกจากหน้าที่ด้านความปลอดภัย'),[
row(('Category','ประเภทตามกลไก'),('Technical, administrative or physical?','Technical, Administrative หรือ Physical?'),('Example: a firewall enforces software rules.','ตัวอย่าง: Firewall ใช้กฎในซอฟต์แวร์')),
row(('Function','หน้าที่'),('What is it doing in this scenario?','ในสถานการณ์นี้มาตรการทำอะไร?'),('Example: blocking an unauthorised connection.','ตัวอย่าง: บล็อกการเชื่อมต่อที่ไม่ได้รับอนุญาต'))],
('A §35 and B §6 distinguish a control category from its function. A category describes how the safeguard is implemented; a function describes what it does in the stated situation. The official Objective 1.4 uses technical, administrative and physical categories. A software firewall applying a configured connection rule is technical; blocking a connection describes its preventive function. These are different questions, not competing labels. The same security goal may need all three categories, and a single product or service can contain several components. Earlier lessons used encryption, MFA and policy as examples without teaching this taxonomy. This lesson develops category reasoning; the detailed preventive, detective and other function distinctions remain planned for L11. The examples are original teaching scenarios, not predictions of actual exam questions.',
'A §35 และ B §6 แยกประเภทของ Control ออกจากหน้าที่ Category อธิบายว่ามาตรการใช้กลไกอะไร ส่วน Function อธิบายว่าทำอะไรในสถานการณ์นั้น Objective 1.4 ทางการใช้ Technical, Administrative และ Physical Firewall ที่ใช้ซอฟต์แวร์บังคับกฎการเชื่อมต่อเป็น Technical ส่วนการบล็อกการเชื่อมต่อบอกหน้าที่เชิงป้องกัน เป็นคนละคำถาม ไม่ใช่คำตอบที่แข่งกัน เป้าหมายเดียวอาจต้องใช้ทั้งสามประเภท และผลิตภัณฑ์หรือบริการเดียวอาจมีหลายองค์ประกอบ บทก่อนใช้ Encryption, MFA และ Policy เป็นตัวอย่างแต่ยังไม่ได้สอนการจัดหมวด บทนี้พัฒนาเหตุผลเรื่อง Category ส่วนรายละเอียด Preventive, Detective และหน้าที่อื่นยังเป็นแผน L11 ตัวอย่างแต่งขึ้นเพื่อเรียน ไม่ใช่การทำนายข้อสอบจริง'),('Mechanism = category. Purpose in context = function.','กลไกบอก Category ส่วนงานในบริบทบอก Function'))
add('02-technical-enforcement','technical',('Technical controls apply rules through technology.','Technical Controls ใช้เทคโนโลยีบังคับกฎ'),('Hardware and software enforce configured security decisions.','ฮาร์ดแวร์และซอฟต์แวร์ทำตามการตัดสินใจที่ตั้งค่าไว้'),[
row(('Request','คำร้องขอ'),('A user requests access to a record.','ผู้ใช้ขอเข้าถึงข้อมูล'),('Identity alone does not grant every permission.','รู้ตัวตนไม่ได้ให้ทุกสิทธิ์')),
row(('Enforcement','การบังคับใช้'),('An ACL checks the allowed action.','ACL ตรวจว่าการกระทำนั้นได้รับอนุญาตไหม'),('Configured rules determine the result.','กฎที่ตั้งไว้กำหนดผล')),
row(('Result','ผล'),('Permit or deny the requested action.','อนุญาตหรือปฏิเสธการกระทำ'),('Test the rule and review changes.','ทดสอบกฎและทบทวนการเปลี่ยน'))],
('A §36 lists encryption, authentication mechanisms, ACLs, firewalls and IDS/IPS as technical examples; B §6.1 calls the category technical/logical. These controls operate through hardware or software: an ACL can enforce allowed actions, MFA checks authentication factors and encryption protects data using cryptographic keys. Those mechanisms have different purposes; technical does not mean that every tool provides every security property. In this authored records example, a valid login does not override an ACL that denies a particular action. People select and configure technology, but that involvement does not make the actual automated enforcement an administrative control. An approved access policy and a human review process are separate administrative components. Misconfiguration, key handling or gaps can still undermine protection; purchasing a tool is not proof that it works. Detailed access models and product configuration remain outside this introductory category unit.',
'A §36 ยก Encryption กลไก Authentication, ACL, Firewall และ IDS/IPS เป็นตัวอย่าง Technical ส่วน B §6.1 ใช้คำ Technical/Logical มาตรการเหล่านี้ทำงานผ่านฮาร์ดแวร์หรือซอฟต์แวร์ เช่น ACL บังคับสิทธิ์การกระทำ MFA ตรวจปัจจัย และ Encryption ปกป้องข้อมูลด้วยกุญแจ แต่ละกลไกมีจุดประสงค์ต่างกัน คำว่า Technical ไม่ได้แปลว่าเครื่องมือทุกตัวปกป้องได้ทุกด้าน ในตัวอย่างข้อมูลแต่งขึ้น การ Login สำเร็จไม่ได้ข้าม ACL ที่ปฏิเสธงานบางอย่าง คนเป็นผู้เลือกและตั้งค่าเทคโนโลยี แต่การบังคับใช้อัตโนมัติยังเป็น Technical ส่วน Policy ที่อนุมัติและกระบวนการทบทวนโดยคนเป็นองค์ประกอบ Administrative แยกกัน การตั้งค่าผิด การจัดการกุญแจ หรือช่องว่างยังทำให้ปกป้องไม่ได้ ซื้อเครื่องมือไม่ใช่หลักฐานว่าได้ผล รายละเอียดโมเดลสิทธิ์และการตั้งค่าผลิตภัณฑ์อยู่นอกบทพื้นฐานนี้'),('Classify the enforcement—not the person configuring it.','ดูการบังคับใช้ ไม่ใช่ดูแค่คนที่ตั้งค่า'))
add('03-administrative-direction','administrative',('Administrative controls organise people and decisions.','Administrative Controls จัดคน กระบวนการ และการตัดสินใจ'),('Direction, approved processes and oversight make security repeatable.','ทิศทาง กระบวนการที่อนุมัติ และการกำกับช่วยให้งานสม่ำเสมอ'),[
row(('Direction','ทิศทาง'),('Set policy and assign responsibilities.','กำหนด Policy และผู้รับผิดชอบ'),('Builds on the document roles in L09.','ต่อจากหน้าที่เอกสารใน L09')),
row(('People & process','คนและกระบวนการ'),('Train staff and review access approvals.','ฝึกพนักงานและทบทวนการอนุมัติสิทธิ์'),('A human decision process.','เป็นกระบวนการตัดสินใจโดยคน')),
row(('Oversight','การกำกับ'),('Assess risk and check evidence.','ประเมิน Risk และตรวจหลักฐาน'),('Confirm the process is used.','ตรวจว่าทำตามกระบวนการจริง'))],
('B §6.1 groups policy, awareness training and risk assessment as administrative/managerial controls. A §36 adds planning, vendor management, hiring checks, classification and human operational processes. Administrative controls guide behaviour, allocate responsibility and organise decisions. This authored example combines approved policy, staff preparation, access approval and review evidence. A policy statement alone does not configure a system or guarantee that people follow it; it needs implementation, ownership and checking. Equally, the fact that a reviewer stores a decision in a software ticket does not turn the human approval process into technical enforcement. The system rule that then applies permissions is a distinct technical component. L09 already teaches policy, standard, procedure and guideline functions; this slide uses those artifacts as controls rather than repeating the document lesson. A control may combine people, process and technology, so identify the component actually described.',
'B §6.1 จัด Policy, Awareness Training และ Risk Assessment เป็น Administrative/Managerial ส่วน A §36 เพิ่มการวางแผน ผู้ให้บริการ การตรวจบุคลากร การจัดชั้นข้อมูล และกระบวนการปฏิบัติงานโดยคน Administrative ชี้พฤติกรรม มอบหมายหน้าที่ และจัดการตัดสินใจ ตัวอย่างแต่งขึ้นนี้เชื่อมนโยบายที่อนุมัติ การเตรียมพนักงาน การอนุมัติสิทธิ์ และหลักฐานทบทวน ข้อความ Policy อย่างเดียวไม่ได้ตั้งค่าระบบหรือรับประกันว่าคนทำตาม ต้องมีเจ้าของ การนำไปใช้ และการตรวจ การเก็บผลอนุมัติใน Ticket ซอฟต์แวร์ก็ไม่ได้ทำให้กระบวนการตัดสินใจของคนกลายเป็น Technical ส่วนกฎระบบที่ใช้สิทธิ์เป็นองค์ประกอบ Technical แยกกัน L09 สอนหน้าที่เอกสารแล้ว สไลด์นี้ใช้เอกสารเป็น Control ไม่สอนบทเดิมซ้ำ มาตรการอาจรวมคน กระบวนการ และเทคโนโลยี จึงต้องดูองค์ประกอบที่อธิบายจริง'),('A documented process needs people, ownership and evidence.','กระบวนการที่เขียนไว้ยังต้องมีคน เจ้าของงาน และหลักฐาน'))
add('04-physical-protection','physical',('Physical controls protect spaces and tangible assets.','Physical Controls ปกป้องพื้นที่และทรัพย์สินที่จับต้องได้'),('The protected boundary matters—even when the device is electronic.','ดูขอบเขตที่ปกป้อง แม้อุปกรณ์จะเป็นอิเล็กทรอนิกส์'),[
row(('Facility boundary','ขอบเขตสถานที่'),('A locked door limits entry to the server room.','ประตูล็อกจำกัดการเข้าห้อง Server'),('An electronic door lock is still physical protection.','ล็อกอิเล็กทรอนิกส์ยังปกป้องพื้นที่')),
row(('People & equipment','คนและอุปกรณ์'),('Guards, barriers and secured devices protect the site.','เจ้าหน้าที่ รั้วกั้น และอุปกรณ์ยึดล็อกช่วยดูแลพื้นที่'),('Logical account permissions are a separate component.','สิทธิ์บัญชีในระบบเป็นอีกองค์ประกอบ'))],
('A §36 and B §6.1 give guards, fences, door locks, cameras, alarms and secured equipment as physical examples. They protect facilities, access to spaces and tangible assets; power and environmental safeguards can also protect a physical operating environment. In the authored server-room illustration, the locked boundary controls entry while a guard checks physical access according to procedure. A guard is not automatically an administrative category just because a person performs the task. Nor does an electronic lock become purely logical protection because it uses technology: the stated mechanism restricts entry through a physical door. A badge system may contain technical identity/rule processing, administrative authorisation and physical lock components. Classify the component and protected boundary described rather than treating the entire product as one universal label. Cameras may serve different functions, whose detailed distinctions remain for L11. Physical protection does not replace logical permissions or data handling.',
'A §36 และ B §6.1 ยกเจ้าหน้าที่ รั้ว ประตูล็อก กล้อง สัญญาณเตือน และอุปกรณ์ยึดล็อกเป็นตัวอย่าง Physical เพื่อดูแลสถานที่ การเข้าพื้นที่ และทรัพย์สินจริง มาตรการไฟฟ้าและสภาพแวดล้อมก็ช่วยรักษาสภาพการทำงานได้ ภาพห้อง Server แต่งขึ้นแสดงขอบเขตล็อกและเจ้าหน้าที่ตรวจการเข้าตามขั้นตอน เจ้าหน้าที่ไม่ได้เป็น Administrative อัตโนมัติเพียงเพราะเป็นคน และล็อกอิเล็กทรอนิกส์ก็ไม่ได้กลายเป็น Logical อย่างเดียว เพราะกลไกที่อธิบายจำกัดการผ่านประตูจริง ระบบบัตรอาจมีส่วนตรวจตัวตนและกฎแบบ Technical การอนุมัติแบบ Administrative และตัวล็อก Physical ต้องแยกองค์ประกอบกับขอบเขตที่ปกป้อง ไม่ติดป้ายเดียวกับทุกส่วนของผลิตภัณฑ์ กล้องทำได้หลายหน้าที่ซึ่งจะสอนรายละเอียดใน L11 การปกป้องพื้นที่ไม่แทนสิทธิ์ระบบหรือการจัดการข้อมูล'),('Electronic does not mean “technical only.”','อิเล็กทรอนิกส์ไม่ได้แปลว่าเป็น Technical อย่างเดียว'))
add('05-course-labels','labels',('Read the course labels without adding an official category.','อ่านคำในคอร์สให้เข้าใจ โดยไม่เพิ่มหมวดทางการ'),('Managerial and operational describe useful people/process distinctions.','Managerial และ Operational ช่วยแยกการบริหารกับงานประจำ'),[
row(('Managerial','Managerial'),('Policy, planning and risk oversight.','นโยบาย แผน และการกำกับ Risk'),('A useful course supporting label.','เป็นคำแบ่งเสริมในคอร์ส')),
row(('Operational','Operational'),('People carry out recurring security processes.','คนทำกระบวนการความปลอดภัยประจำ'),('Identify the actual component.','ยังต้องดูองค์ประกอบที่ทำงานจริง'))],
('A §36 uses four course labels: technical, managerial, operational and physical. B §6.1 instead groups administrative/managerial, technical/logical and physical; the official 2026 Objective 1.4 lists technical, administrative and physical. Managerial and operational are useful supporting labels, not a fourth official category to add to the outline. In this lesson, policy/planning and people-led recurring processes are discussed within the administrative perspective. That is an instructional reconciliation, not a universal assertion that every operational activity is administrative. A backup procedure and a person reviewing restore evidence are process elements, while the backup software and encryption mechanisms are technical components. Configuration approval is a process; automated enforcement of a configuration rule is technology. Avoid classifying by the word operational alone. Different taxonomies can be useful; answer the category question using the stated scheme and actual mechanism. Detailed control functions remain L11.',
'A §36 ใช้สี่คำในคอร์สคือ Technical, Managerial, Operational และ Physical แต่ B §6.1 ใช้ Administrative/Managerial, Technical/Logical และ Physical ส่วน Objective 1.4 ปี2026 ทางการระบุ Technical, Administrative และ Physical คำ Managerial กับ Operational เป็นคำเสริมที่ช่วยเข้าใจ ไม่ใช่หมวดทางการที่สี่ที่จะเพิ่มเข้า Outline บทนี้อธิบายนโยบายและแผน รวมถึงกระบวนการประจำที่คนทำ ในมุม Administrative เป็นการเทียบเพื่อเรียน ไม่ใช่กฎว่าทุกกิจกรรม Operational ต้องเป็น Administrative Procedure สำรองข้อมูลและคนทบทวนหลักฐานกู้คืนเป็นส่วนกระบวนการ ส่วนซอฟต์แวร์ Backup และ Encryption เป็น Technical การอนุมัติตั้งค่าเป็นกระบวนการ แต่ระบบบังคับค่าตามกฎเป็นเทคโนโลยี อย่าจัดประเภทด้วยคำ Operational อย่างเดียว หลาย Taxonomy มีประโยชน์ได้ แต่ต้องใช้ชุดที่โจทย์ระบุและกลไกจริง หน้าที่ Control โดยละเอียดยังเป็น L11'),('Official 1.4 categories: Technical · Administrative · Physical.','หมวดทางการ 1.4: Technical · Administrative · Physical'))
add('06-one-goal-three-controls','together',('One records service needs complementary controls.','บริการข้อมูลหนึ่งระบบต้องใช้มาตรการที่เสริมกัน'),('Protect authorised access across decisions, systems and spaces.','ดูแลการเข้าถึงที่ได้รับอนุญาตทั้งการตัดสินใจ ระบบ และพื้นที่'),[
row(('Administrative','Administrative'),('Approve access and review role changes.','อนุมัติสิทธิ์และทบทวนเมื่อหน้าที่เปลี่ยน'),('Who should have access?','ใครควรมีสิทธิ์?')),
row(('Technical','Technical'),('Enforce permissions on the records system.','บังคับสิทธิ์ในระบบข้อมูล'),('Can this account perform this action?','บัญชีนี้ทำงานนี้ได้หรือไม่?')),
row(('Physical','Physical'),('Restrict entry to the equipment room.','จำกัดการเข้าห้องอุปกรณ์'),('Who can reach the hardware?','ใครเข้าถึงฮาร์ดแวร์จริงได้?'))],
('A §§35–36 and B §6.1 supply the category distinctions; NIST SP 800-12 Rev.1 §2.6 explains that security controls have interdependencies and work as an integrated approach. This original clinic records example uses administrative access approval/review, technical permission enforcement and physical equipment-room protection toward one goal. A locked room does not stop an already authorised network account from misusing data, and an ACL does not decide whether an employee still has a business need unless the approval and review process keeps it current. Each layer has a scope and limitations; the combination still requires testing. Do not map categories one-to-one to CIA: all three categories can support confidentiality, integrity and availability depending on design. This is a short category integration example, not a new detailed network architecture/defense-in-depth unit. The official networking architecture depth remains elsewhere; L11 will examine what each control is doing in a stated event.',
'A §§35–36 และ B §6.1 ให้การแยก Category ส่วน NIST SP800-12 Rev.1 §2.6 อธิบายว่า Controls พึ่งพากันและควรทำงานร่วม ตัวอย่างระบบข้อมูลคลินิกแต่งขึ้นใช้การอนุมัติและทบทวนแบบ Administrative การบังคับสิทธิ์ Technical และการดูแลห้องอุปกรณ์ Physical เพื่อเป้าหมายเดียว ห้องล็อกไม่หยุดบัญชีเครือข่ายที่มีสิทธิ์จากการใช้ข้อมูลผิด และ ACL ไม่รู้เองว่าพนักงานยังจำเป็นต้องใช้ข้อมูลหรือไม่ หากกระบวนการอนุมัติและทบทวนไม่ปรับให้ทัน แต่ละส่วนมีขอบเขตและข้อจำกัด แม้รวมกันก็ยังต้องทดสอบ อย่าจับคู่ Category กับ CIA แบบหนึ่งต่อหนึ่ง ทั้งสามประเภทช่วย Confidentiality, Integrity และ Availability ได้ตามการออกแบบ นี่เป็นตัวอย่างเชื่อมหมวดสั้น ๆ ไม่ใช่บทสถาปัตยกรรมเครือข่ายหรือ Defense in Depth ใหม่ รายละเอียดส่วนนั้นอยู่ที่อื่น และ L11 จะวิเคราะห์หน้าที่ของ Control ในเหตุการณ์'),('Combine controls; check the gaps between them.','ใช้มาตรการร่วมกัน และตรวจช่องว่างระหว่างส่วน'))
add('07-classify-the-mechanism','classify',('Classify the review—not the ticketing tool.','จัดประเภทงานทบทวน ไม่ใช่เครื่องมือ Ticket'),('A manager reviews access requests and records approval in a ticket.','ผู้จัดการทบทวนคำขอสิทธิ์ แล้วบันทึกการอนุมัติใน Ticket'),[
row(('Technical','Technical'),('Software enforcement would be technical.','การบังคับใช้โดยซอฟต์แวร์เป็น Technical'),('The described control is a human review.','แต่สิ่งที่อธิบายคือการทบทวนโดยคน')),
row(('Administrative','Administrative'),('A person applies an approved decision process.','คนใช้กระบวนการตัดสินใจที่อนุมัติ'),('The ticket stores evidence of the review.','Ticket เก็บหลักฐานการทบทวน')),
row(('Physical','Physical'),('A physical control restricts space or equipment access.','Physical ดูแลการเข้าพื้นที่หรืออุปกรณ์จริง'),('No physical boundary is being operated here.','กรณีนี้ไม่ได้ใช้ขอบเขตพื้นที่จริง'))],
('This original non-scored exercise applies A §35–36 and B §6.1. It asks for the mechanism of the human access-request review, not the category of every component in the ticketing product. Administrative is the best answer because a manager follows an approval process and records a decision. A ticket being electronic does not make that judgement software enforcement. If a separate system automatically applies the approved permissions, that enforcement is technical. A locked door controlling entry to equipment would be physical. Both languages explain every choice, and native buttons support keyboard activation. No question bank, score or progress schema is changed; the choice is temporary viewer interaction state. Use the stated mechanism, scope and taxonomy rather than a superficial keyword such as computer or manager. Real systems can combine all three components.',
'แบบฝึกแต่งขึ้นไม่มีคะแนนนี้ใช้ A §§35–36 และ B §6.1 โดยถามกลไกของงานทบทวนคำขอสิทธิ์โดยคน ไม่ใช่ประเภททุกส่วนของผลิตภัณฑ์ Ticket Administrative ตรงที่สุดเพราะผู้จัดการทำตามกระบวนการอนุมัติและบันทึกผล Ticket เป็นอิเล็กทรอนิกส์ไม่ได้ทำให้ดุลยพินิจนั้นเป็นการบังคับใช้โดยซอฟต์แวร์ ถ้าระบบอีกส่วนใช้สิทธิ์ที่อนุมัติโดยอัตโนมัติ ส่วนนั้นเป็น Technical ส่วนประตูล็อกที่จำกัดการเข้าห้องอุปกรณ์เป็น Physical มีเหตุผลทุกตัวเลือกทั้งสองภาษา และปุ่มมาตรฐานใช้คีย์บอร์ดได้ ไม่แตะคลังข้อสอบ คะแนน หรือโครงสร้าง Progress คำตอบเป็นสถานะปฏิสัมพันธ์ชั่วคราวใน Viewer ให้ดูชุดประเภท กลไก และขอบเขตที่ระบุ ไม่ใช่แค่คำว่า Computer หรือ Manager ระบบจริงรวมได้ทั้งสามส่วน'),('Identify the mechanism actually described.','ระบุกลไกที่สถานการณ์อธิบายจริง'))
add('08-select-and-check','decision',('Choose the mechanism, assign an owner, verify the result.','เลือกกลไก มอบหมายเจ้าของ แล้วตรวจผล'),('A category is a way to reason—not proof that a control works.','Category ช่วยวิเคราะห์ แต่ไม่ใช่หลักฐานว่า Control ได้ผล'),[
row(('Scope','ขอบเขต'),('What asset, risk and boundary are involved?','เกี่ยวกับ Asset, Risk และขอบเขตใด?'),('Avoid choosing by product name alone.','อย่าเลือกจากชื่อผลิตภัณฑ์อย่างเดียว')),
row(('Mechanism & owner','กลไกและเจ้าของงาน'),('Choose people/process, technology or physical protection.','เลือกคน/กระบวนการ เทคโนโลยี หรือการปกป้องพื้นที่'),('Clarify responsibilities between components.','ระบุหน้าที่ระหว่างส่วนให้ชัด')),
row(('Evidence','หลักฐาน'),('Test operation and review changes.','ทดสอบการทำงานและทบทวนการเปลี่ยน'),('A control may fail despite the right label.','ติดป้ายถูกก็ยังทำงานผิดได้'))],
('A §§35–36 and B §6.3 encourage reading what a control actually does and which aspect the question asks about. NIST SP800-12 Rev.1 §§2.4,2.6–2.7 support explicit responsibility, integrated safeguards and recurring assessment. This authored decision record starts with an asset and risk, identifies the described mechanism, assigns an appropriate owner and asks for evidence that it works. For a records service, a policy review, permission rule and room lock have different owners and checks; none is automatically sufficient by itself. When an implementation mixes categories, break it into components and explain the stated focus. This lesson teaches the three official category headings with practical distinctions and reconciles the course taxonomy. It does not replace L11 detailed preventive/detective/corrective and other function reasoning, or L12 ethics. Coverage status should reflect that remaining instructional depth rather than the publication flag alone.',
'A §§35–36 และ B §6.3 แนะนำให้อ่านว่ามาตรการทำอะไรจริงและคำถามถามมุมใด NIST SP800-12 Rev.1 §§2.4,2.6–2.7 สนับสนุนหน้าที่ชัด การใช้มาตรการร่วม และการประเมินต่อเนื่อง บันทึกตัดสินใจแต่งขึ้นนี้เริ่มจาก Asset และ Risk ระบุกลไก มอบหมายเจ้าของที่เหมาะ และขอหลักฐานว่าใช้ได้จริง ระบบข้อมูลอาจมีคนตรวจ Policy กฎสิทธิ์ และล็อกห้อง ซึ่งมีเจ้าของและวิธีตรวจต่างกัน ไม่มีส่วนใดพอโดยอัตโนมัติ ถ้าระบบผสมประเภท ให้แยกองค์ประกอบและอธิบายจุดที่กล่าวถึง บทนี้สอนสามหมวดทางการพร้อมแยกตัวอย่างและเทียบ Taxonomy ในคอร์ส แต่ไม่แทน L11 ที่วิเคราะห์หน้าที่ Preventive/Detective/Corrective และแบบอื่น หรือ L12 Ethics สถานะ Coverage จึงควรสะท้อนความลึกที่ยังเหลือ ไม่ดูแค่สถานะ Published'),('Next depth: control functions remain planned for Lesson 11.','ความลึกถัดไป: หน้าที่ Controls ยังเป็นแผน Lesson 11'))
l.update(id='lesson-d1-10-control-categories',primaryObjectiveId='1.4',objectiveIds=['1.4'],title=pair('Control Categories','ประเภทของมาตรการความปลอดภัย'),synopsis=pair('Distinguish technical, administrative and physical controls by mechanism and apply them together.','แยก Technical, Administrative และ Physical ตามกลไก และใช้ร่วมกันให้เหมาะสม'),outcomes=[pair('Separate a control category from its function in context.','แยก Category ของ Control ออกจากหน้าที่ในบริบท'),pair('Explain technical, administrative and physical mechanisms with realistic examples.','อธิบายกลไก Technical, Administrative และ Physical ด้วยตัวอย่างจริงที่เข้าใจได้'),pair('Reconcile managerial/operational course labels without inventing a fourth official category.','เทียบ Managerial/Operational ในคอร์ส โดยไม่เพิ่มหมวดทางการที่สี่'),pair('Classify a described component and identify complementary safeguards and evidence.','จัดประเภทองค์ประกอบที่อธิบาย พร้อมระบุมาตรการเสริมและหลักฐาน')],prerequisites=[pair('Recommended: CIA, AAA/MFA, risk foundations and governance/document lessons.','แนะนำพื้นฐาน CIA, AAA/MFA, Risk และ Governance/เอกสาร')],slides=slides,slideOrder=[s['id'] for s in slides])
